package com.nunnun.roommate.repository;
import com.nunnun.roommate.entity.RoommateGroup; import jakarta.persistence.LockModeType; import java.util.Optional; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param;
public interface RoommateGroupRepository extends JpaRepository<RoommateGroup,Long>{ Optional<RoommateGroup> findByInviteCode(String inviteCode); boolean existsByInviteCode(String inviteCode); @Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select g from RoommateGroup g where g.inviteCode=:code") Optional<RoommateGroup> findByInviteCodeForUpdate(@Param("code") String code); @Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select g from RoommateGroup g where g.id=:groupId") Optional<RoommateGroup> findByIdForUpdate(@Param("groupId") Long groupId); }
